css:
#tongsci1-3-3-4-universal .body.sim { grid-template-columns: 1100px minmax(0, 1fr); }
#tongsci1-3-3-4-universal .un-stage { position: relative; border: 2px solid var(--ink); border-radius: 12px; overflow: hidden; background: linear-gradient(180deg, #f6f8f4 0%, #eef2ee 100%); }
#tongsci1-3-3-4-universal .un-stage canvas { touch-action: none; cursor: pointer; }
#tongsci1-3-3-4-universal .un-stage .now-chip { top: auto; bottom: 12px; left: 50%; transform: translateX(-50%); max-width: 46%; white-space: nowrap; font-size: 18px; padding: 6px 14px; }
#tongsci1-3-3-4-universal .un-panel { gap: 12px; }
#tongsci1-3-3-4-universal .un-out { margin: 0; font-size: 20px; line-height: 1.45; background: #fffbe6; border: 2px solid var(--accent); border-radius: 12px; padding: 7px 14px; min-height: 4.4em; flex: none; }
#tongsci1-3-3-4-universal .un-think { border: 2px solid var(--ink); border-radius: 12px; background: var(--paper-2); padding: 8px 14px 10px; flex: none; }
#tongsci1-3-3-4-universal .un-think > b { font: 800 18px var(--f-body); color: var(--accent); }
#tongsci1-3-3-4-universal .un-think p { margin: 4px 0 0; font-size: 19px; line-height: 1.45; }
#tongsci1-3-3-4-universal .un-think .un-ans { display: none; border-top: 1.5px dashed var(--rule); padding-top: 6px; color: var(--ink); }
#tongsci1-3-3-4-universal .un-think.open .un-ans { display: block; animation: u-pop .5s ease both; }
#tongsci1-3-3-4-universal.u-done .un-out { display: none; }

